def transform_v12(grid):
    height, width = len(grid), len(grid[0])

    # Find components
    visited = [[False] * width for _ in range(height)]
    comps = []

    for r in range(height):
        for c in range(width):
            if grid[r][c] != 0 and not visited[r][c]:
                comp = []
                queue = [(r, c)]
                visited[r][c] = True
                while queue:
                    cr, cc = queue.pop(0)
                    comp.append((cr, cc))
                    color = grid[cr][cc]
                    for dr, dc in [(-1,0),(1,0),(0,-1),(0,1)]:
                        nr, nc = cr + dr, cc + dc
                        if 0 <= nr < height and 0 <= nc < width:
                            if not visited[nr][nc] and grid[nr][nc] == color:
                                visited[nr][nc] = True
                                queue.append((nr, nc))
                comps.append(comp)

    # Latest-tied components by size DESC
    results = sorted(comps, key=lambda c: -len(c))

    output = [[0] * width for _ in range(height)]
    cur_col = width - 1

