def transform_v18(grid, width):
    h, w = len(grid), len(grid[0])
    comps = find_components(grid)

    # Sort by max_col DESC, then by size DESC
    def get_max_col(c):
        return max(p[1] for p in c)

    sorted_comps = sorted(comps, key=lambda c: (-get_max_col(c), -len(c)))

    # Place components
    result = [[0] * w for _ in range(h)]

    for i, comp in enumerate(sorted_comps):
        coords = comp
        min_c = min(p[1] for p in coords)
        comp_width = get_max_col(coords) - min_c + 1

        # Place component: output_min_col = width - comp_width (right-aligned)
        output_min_col = width - comp_width

        for r, c in coords:
            output_c = c - min_c + output_min_col
            if 0 <= r < h and 0 <= output_c < w:
