def transform_by_row_max(grid, width):
    h, w = len(grid), len(grid[0])

    # Group by value
    value_positions = {}
    for r in range(h):
        for c in range(w):
            v = grid[r][c]
            if v != 0:
                if v not in value_positions:
                    value_positions[v] = []
                value_positions[v].append((r, c))

    # Compute max_row for each value
    value_max_rows = {v: max(r for r, c in positions) for v, positions in value_positions.items()}

    # Rank by max_row DESC
    sorted_values = sorted(value_max_rows.keys(), key=lambda v: value_max_rows[v], reverse=True)

    # Place right-aligned
    results = [[0] * w for _ in range(h)]

    rank = 0
    for val in sorted_values:
        positions = value_positions[val]
        rows = [r for r, c in positions]

        # Width of value in terms of cells
        num_cells = len(positions)

        # Output span for this value
        # Formula: output spans [w - 1 - (rank + num_cells - 1), w - 1]
        output_min_col = w - 1 - rank - num_cells + 1

        # Place cells
        for r, c in positions:
            if 0 <= r < h and 0 <= output_min_col <= w - 1:
                results[r][output_min_col] = val

        rank += 1

    return results

